import re

# Get all businesses with relevant fields
biz = list(db['business'].find({}, {'business_id':1,'attributes':1,'description':1}))
print('Total businesses:', len(biz))

# Define WiFi predicate
def wifi_offered(attrs):
    if not isinstance(attrs, dict):
        return False
    # tolerate variants
    val = None
    for k in ('WiFi', 'wifi', 'Wifi'):
        if k in attrs:
            val = attrs[k]
            break
    if val is None:
        return False
    if not isinstance(val, str):
        return False
    # normalize: strip leading u, surrounding quotes
    v = val.strip()
    if v.startswith('u'):
        v = v[1:]
    v = v.strip("'\"").lower()
    return v not in ('no', 'none', '')

US_STATES = {
    'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD',
    'MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC',
    'SD','TN','TX','UT','VT','VA','WA','WV','WI','WY','DC'
}

zip_re = re.compile(r'\b([A-Z]{2})\b\s*\d{5}')
comma_re = re.compile(r',\s*([A-Z]{2})\b')

def parse_state(desc):
    if not isinstance(desc, str):
        return None
    m = zip_re.search(desc)
    if m and m.group(1) in US_STATES:
        return m.group(1)
    m = comma_re.search(desc)
    if m and m.group(1) in US_STATES:
        return m.group(1)
    return None

records = []
for b in biz:
    if wifi_offered(b.get('attributes')):
        st = parse_state(b.get('description'))
        if st:
            records.append((b['business_id'], st))

import pandas as pd
df = pd.DataFrame(records, columns=['business_id','state'])
print('WiFi-offering w/ state:', len(df))
counts = df['state'].value_counts()
print(counts.head(10))
top_state = counts.idxmax()
top_count = counts.max()
# tie check
ties = counts[counts == top_count].index.tolist()
if len(ties) > 1:
    top_state = sorted(ties)[0]
print('top_state:', top_state, 'count:', top_count, 'ties:', ties)

wifi_biz_ids = set(df.loc[df['state']==top_state, 'business_id'])
print('biz in top state:', len(wifi_biz_ids))
